from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _ledger(data, sequence_first, discounted):
    def rounded(n, mode):
        if mode == "half_up":
            return (n + 5000) // 10000
        return n // 10000

    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            key = (seq, event.get("revision", 0), pos)
        else:
            key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        tax_base = net if discounted else raw
        tax = rounded(tax_base * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    options = {}
    for name in names:
        opts = [-1]
        for version in sorted(rows[name]):
            if version in blocked.get(name, []):
                continue
            if name in pins and pins[name] != version:
                continue
            opts.append(version)
        options[name] = opts

    best = None
    best_versions = None
    assignment = {}

    def check():
        for name, (low, high) in roots.items():
            version = assignment.get(name, -1)
            if version < low or version > high:
                return

        edges = {}
        for name, version in assignment.items():
            if version < 0:
                continue
            row = rows[name][version]
            active = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                depname = dep["name"]
                depver = assignment.get(depname, -1)
                if depver < dep["min"] or depver > dep["max"]:
                    return
                active.append(depname)
            edges[name] = active

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            version = assignment.get(name, -1)
            if version < 0:
                return
            reachable.add(name)
            stack.extend(edges.get(name, []))
        installed = {name for name, version in assignment.items() if version >= 0}
        if installed != reachable:
            return

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        if any(not visit(name) for name in reachable):
            return
        vector = tuple(assignment[name] for name in names)
        nonlocal_best(vector)

    def nonlocal_best(vector):
        nonlocal best, best_versions
        if best is None or vector < best:
            best = vector
            best_versions = {name: version for name, version in zip(names, vector)
                             if version >= 0}

    def search(index):
        if index == len(names):
            check()
            return
        name = names[index]
        for version in options[name]:
            assignment[name] = version
            search(index + 1)
        assignment.pop(name, None)

    search(0)
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _quota_intervals(data):
    from itertools import combinations

    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    if not mandatory.issubset({job["id"] for job in options}) or k > len(options):
        return {"error": "impossible"}
    best_value = None
    best_ids = None
    for subset in combinations(options, k):
        ids = sorted(job["id"] for job in subset)
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        end = None
        valid = True
        for job in ordered:
            if end is not None and job["start"] < end:
                valid = False
                break
            end = job["end"]
        if not valid:
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    import heapq

    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    initial_mask = bit.get(start_node, 0)
    coupons = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    initial = (start_node, initial_mask, 0)
    dist = {initial: data["start"]}
    heap = [(data["start"], start_node, initial_mask, 0)]
    while heap:
        time, node, mask, used = heapq.heappop(heap)
        state = (node, mask, used)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and used == coupons:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            for spend in (0, 1):
                if spend and used == coupons:
                    continue
                duration = edge["duration"]
                if spend:
                    duration = max(2, duration - edge.get("discount", 0))
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_used = used + spend
                next_state = (next_node, next_mask, next_used)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(heap, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda data: _ledger(data, True, True),
    "component_02": lambda data: _ledger(data, False, False),
    "component_03": lambda data: _ledger(data, True, False),
    "component_04": lambda data: _ledger(data, False, True),
    "component_05": lambda data: _ledger(data, True, True),
    "component_06": _dependency_resolver,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
